    # TODO: two anagrams share the same sorted letters - use that as a key.
    pass

solution:
def group_anagrams(words: list) -> list:
    groups = {}
    for word in words:
        key = ''.join(sorted(word))
        groups.setdefault(key, []).append(word)
    return list(groups.values())
